<?php
declare(strict_types=1);
function field(string $name,string $label,string $value='',string $type='text',bool $required=true,int $max=200):void{echo '<label>'.e($label).'<input type="'.e($type).'" name="'.e($name).'" value="'.($type==='password'?'':e($_POST[$name]??$value)).'" '.($required?'required':'').' maxlength="'.$max.'"'.($type==='password'&&in_array($name,['password','new_password'],true)?' minlength="12" autocomplete="new-password"':'').'></label>';}
function area(string $name,string $label,string $value='',int $max=3000):void{echo '<label>'.e($label).'<textarea name="'.e($name).'" required maxlength="'.$max.'">'.e($_POST[$name]??$value).'</textarea></label>';}
function selectField(string $name,string $label,array $options,string $value=''):void{echo '<label>'.e($label).'<select name="'.e($name).'" required>';foreach($options as $key=>$text)echo '<option value="'.e($key).'" '.((string)($_POST[$name]??$value)===(string)$key?'selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function stateSelect(string $value='SC'):void{selectField('state','Estado',array_combine(states(),states()),$value);}
function beginForm(string $action,string $class='modal-form'):void{echo '<form method="post" class="'.e($class).'">'.csrfField().'<input type="hidden" name="action" value="'.e($action).'">';}
function submit(string $text):void{echo '<button class="button primary" type="submit">'.e($text).'</button></form>';}
function hidden(string $name,mixed $value):void{echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';}
function pill(string $status):string{$names=['ACTIVE'=>'Publicado','PENDING'=>'Em revisão','REJECTED'=>'Recusado','PAUSED'=>'Pausado','TRADED'=>'Trocado','DELETED'=>'Excluído','OPEN'=>'Aberta','ACCEPTED'=>'Aceita','COMPLETED'=>'Troca concluída','CLOSED'=>'Encerrada','BANNED'=>'Suspenso','RESOLVED'=>'Resolvida','QUEUED'=>'Na fila','PROCESSING'=>'Analisando','FAILED'=>'Revisão necessária','DONE'=>'Analisado'];return '<span class="status-pill status-'.e(strtolower($status)).'">'.e($names[$status]??$status).'</span>';}
function card(array $l):void{$photo=cover((int)$l['id']);$u=currentUser();$favorite=$u&&(bool)sql('SELECT user_id FROM favorites WHERE user_id=? AND listing_id=?',[$u['id'],$l['id']])->fetchColumn();echo '<article class="listing-card"><button class="favorite" data-favorite="'.(int)$l['id'].'" aria-pressed="'.($favorite?'true':'false').'" aria-label="Salvar favorito: '.e($l['title']).'">'.icon('heart').'</button><a class="card-open" href="'.e(url('listing',['id'=>$l['id']])).'">';echo $photo?'<img class="real-photo" src="'.e(mediaUrl($photo)).'" alt="'.e($l['title']).'" loading="lazy">':'<span class="no-photo">'.icon(categories()[$l['category']][1]??'swap').'</span>';echo '<span class="card-content"><strong class="card-title">'.e($l['title']).'</strong><span class="card-description">'.e($l['condition_label']).'</span><span class="wanted">'.icon('swap').'<span>Interesse em: '.e($l['wanted']).'</span></span><span class="open-offers">'.($l['open_offers']?'Aceita outras propostas':'Preferência por este item').'</span><span class="card-city">'.icon('pin').e($l['city']).'/'.e($l['state']).'</span></span></a></article>';}
function accountNav():void{echo '<nav class="account-nav" aria-label="Área do usuário">';foreach(['account'=>'Minha conta','my-listings'=>'Meus anúncios','matches'=>'Meus matches','inbox'=>'Conversas'] as $r=>$n)echo '<a href="'.e(url($r)).'">'.e($n).($r==='inbox'?' <span class="notification-count" data-notification-count hidden></span>':'').($r==='matches'&&newMatchCount((int)currentUser()['id'])?' <span class="match-count">'.newMatchCount((int)currentUser()['id']).'</span>':'').'</a>';echo '</nav>';}
function page(string $title,callable $content):void{$u=currentUser();$sprite=file_get_contents(__DIR__.'/icons.svg');?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080d0b"><title><?=e($title)?> | Trokar.ia</title><link rel="icon" href="assets/favicon.svg"><link rel="manifest" href="manifest.webmanifest"><link rel="apple-touch-icon" href="assets/pwa/icon-180.png"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Trokar.ia"><script src="assets/pwa.js?v=1" defer></script><link rel="stylesheet" href="assets/style.css?v=3"><link rel="stylesheet" href="assets/platform.css?v=6-sponsors"><script src="assets/platform.js?v=5-pwa" defer></script><script src="assets/visual-engine.js?v=1" defer></script><script id="visual-config" type="application/json"><?=json_encode(['screen'=>(string)($_GET['r']??'home'),'edits'=>visualConfig((string)($_GET['r']??'home')),'preview'=>isset($_GET['editor_preview'])],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><meta name="csrf-token" content="<?=e(csrf())?>"></head><body<?= $u?' data-notifications="enabled"':'' ?>><a class="skip" href="#main">Ir para o conteúdo</a><?=$sprite?><header class="header"><div class="container header-inner"><a class="wordmark" href="<?=e(url())?>"><img src="assets/logo.svg?v=2" alt="Trokar.ia" width="284" height="60"></a><button class="menu-button icon-button" aria-label="Abrir menu" aria-expanded="false" aria-controls="navigation"><?=icon('menu')?></button><nav id="navigation" aria-label="Menu principal"><a href="<?=e(url())?>">Início</a><a href="<?=e(url('publish'))?>">Anunciar</a><a href="<?=e(url('matches'))?>">Matches</a><a href="<?=e(url('how'))?>">Como funciona</a><a href="<?=e(url('donations'))?>">Doações</a></nav><div class="header-actions"><?php if($u):?><a class="sign-in" href="<?=e(url('inbox'))?>"><?=icon('user')?>Conversas <span class="notification-count" data-notification-count hidden></span></a><a class="button primary" href="<?=e(url('account'))?>">Minha conta</a><?php else:?><a class="sign-in" href="<?=e(url('login'))?>">Entrar</a><a class="button primary" href="<?=e(url('register'))?>">Começar grátis</a><?php endif;?></div></div></header><main class="container platform-main" id="main"><div class="app-tools"><button type="button" class="install-app" data-install-app>Instalar Trokar.ia</button><a class="notification-summary" data-notification-summary href="index.php?r=inbox" hidden aria-live="polite"></a></div><?php if(isset($_SESSION['flash'])):?><div class="notice" role="status"><?=e($_SESSION['flash'])?></div><?php unset($_SESSION['flash']);endif;?><?php if(!empty($GLOBALS['page_error'])):?><div class="notice error" role="alert"><?=e($GLOBALS['page_error'])?></div><?php endif;?><?php $content();?></main><footer><div class="container footer-main"><a class="wordmark" href="<?=e(url())?>"><img src="assets/logo.svg?v=2" alt="Trokar.ia" width="284" height="60"></a><p>Troque. Conecte. Dê um novo ciclo.</p><div><a href="<?=e(url('sponsors'))?>">Para empresas</a><a href="<?=e(url('contact'))?>">Contato</a><a href="<?=e(url('privacy'))?>">Privacidade</a><a href="<?=e(url('rules'))?>">Regras</a></div></div><div class="container footer-bottom"><span>© <?=date('Y')?> Trokar.ia · trokar.ia.br</span><span>Gratuito para anunciar e trocar. A negociação é entre as pessoas.</span></div></footer><div id="toast" role="status" aria-live="polite"></div></body></html><?php }
function renderHome():void{
 $category=(string)($_GET['category']??'all');if(!isset(categories()[$category]))$category='all';$q=mb_substr(trim((string)($_GET['q']??'')),0,100);$city=mb_substr(trim((string)($_GET['city']??'')),0,120);$state=strtoupper(trim((string)($_GET['state']??'')));if(!in_array($state,states(),true))$state='';$favs=isset($_GET['favorites']);$u=$favs?requireUser():currentUser();$params=[];$where="l.status='ACTIVE' AND u.status='ACTIVE'";if($category!=='all'){$where.=' AND l.category=?';$params[]=$category;}if($q!==''){$where.=" AND (l.title LIKE ? ESCAPE '!' OR l.description LIKE ? ESCAPE '!' OR l.wanted LIKE ? ESCAPE '!')";$like='%'.str_replace(['!','%','_'],['!!','!%','!_'],$q).'%';array_push($params,$like,$like,$like);}if($city!==''){$where.=' AND l.city=?';$params[]=$city;}if($state!==''){$where.=' AND l.state=?';$params[]=$state;}$join=$favs?' JOIN favorites f ON f.listing_id=l.id AND f.user_id='.(int)$u['id']:'';$total=(int)sql('SELECT COUNT(*) FROM listings l JOIN users u ON u.id=l.user_id'.$join.' WHERE '.$where,$params)->fetchColumn();$page=max(1,min(1000,(int)($_GET['page']??1)));$offset=($page-1)*24;$items=sql('SELECT l.* FROM listings l JOIN users u ON u.id=l.user_id'.$join.' WHERE '.$where.' ORDER BY l.created_at DESC,l.id DESC LIMIT 24 OFFSET '.$offset,$params)->fetchAll();
 $cities=sql("SELECT DISTINCT l.city,l.state FROM listings l JOIN users u ON u.id=l.user_id WHERE l.status='ACTIVE' AND u.status='ACTIVE' ORDER BY l.city,l.state")->fetchAll();
 echo file_get_contents(__DIR__.'/hero.html');?>
 <section class="match-banner"><div class="match-banner-icon"><?=icon('spark')?></div><div><p class="eyebrow">O ENCONTRO CERTO COMEÇA COM UMA IDEIA</p><h2>Você anuncia. Os interesses se conectam.</h2><p>Conte o que tem e o que procura. A IA pode entender seus interesses; você continua aberto a outras propostas.</p></div><a class="button outline" href="<?=e(url('matches'))?>">Meus matches <?=icon('arrow')?></a></section>
 <form class="search-bar" role="search" method="get"><input type="hidden" name="r" value="home"><input type="hidden" name="category" value="<?=e($category)?>"><?php if($favs):?><input type="hidden" name="favorites" value="1"><?php endif;?><label class="search-field"><?=icon('search')?><span class="sr-only">Buscar itens</span><input name="q" placeholder="O que você está procurando?" value="<?=e($q)?>" maxlength="100"></label><label class="city-field"><?=icon('pin')?><span class="sr-only">Cidade e estado</span><select name="local"><option value="">Todas as cidades</option><?php foreach($cities as $c):?><option value="<?=e($c['city'].'|'.$c['state'])?>" <?=($city===$c['city']&&$state===$c['state'])?'selected':''?>><?=e($c['city'].'/'.$c['state'])?></option><?php endforeach;?></select></label><button class="button primary" type="submit"><?=icon('search')?> Buscar</button></form>
 <nav class="categories" id="categories" aria-label="Categorias"><?php foreach(['all'=>['Todos','grid']]+categories() as $key=>$c):?><a class="category-button" aria-current="<?=$category===$key?'page':'false'?>" href="<?=e(url('home',array_filter(['category'=>$key,'q'=>$q,'city'=>$city,'state'=>$state,'favorites'=>$favs?1:null],static fn($v)=>$v!==null)))?>"><?=icon($c[1])?><span><?=e($c[0])?></span></a><?php endforeach;?></nav>
 <section class="listings"><div class="section-heading"><div><p class="eyebrow">SEU PRÓXIMO ACHADO ESTÁ AQUI</p><h2><?=$favs?'Seus favoritos':'Explore as possibilidades'?></h2></div><div class="list-controls"><a class="text-button" href="<?=e(url('home',['favorites'=>1]))?>"><?=icon('heart')?> Favoritos</a><a class="text-button" href="<?=e(url())?>">Ver todos <?=icon('arrow')?></a></div></div><p class="listing-meta"><?=$total?> <?=$total===1?'anúncio':'anúncios'?></p><div class="listing-grid"><?php foreach($items as $l)card($l);?></div><?php if(!$items):?><div class="empty-state"><h3><?=$total?'Nenhum anúncio nesta página.':'As próximas trocas começam com você.'?></h3><p>Experimente outra busca ou anuncie um item para encontrar novas possibilidades.</p><a class="button outline" href="<?=e(url('publish'))?>">Anunciar gratuitamente</a></div><?php endif;?><?php if($total>24):?><nav class="pagination" aria-label="Paginação"><?php if($page>1):?><a class="button outline" href="<?=e(url('home',array_merge($_GET,['page'=>$page-1])))?>">Anterior</a><?php endif;?><span>Página <?=$page?></span><?php if($page*24<$total):?><a class="button outline" href="<?=e(url('home',array_merge($_GET,['page'=>$page+1])))?>">Próxima</a><?php endif;?></nav><?php endif;?></section>
 <section class="how-section"><div class="section-heading"><div><p class="eyebrow">SIMPLES DO COMEÇO AO MATCH</p><h2>Trocar faz sentido.</h2></div><span>Sem comprar. Sem vender. Só trocar.</span></div><div class="steps"><article><span class="step-number">01</span><h3>Mostre o que você tem.</h3><p>Uma boa foto, uma descrição honesta e o que você gostaria de receber.</p></article><article><span class="step-number">02</span><h3>Encontre quem combina.</h3><p>Receba sugestões e faça propostas. Não é necessário anunciar para iniciar uma conversa.</p></article><article><span class="step-number">03</span><h3>Conversem e combinem.</h3><p>As pessoas decidem as condições. Confira o item e escolha um local público para o encontro.</p></article></div></section>
 <?php renderSponsorCallout(); ?>
 <section class="donations" id="donations"><div class="donation-icon"><?=icon('heart')?></div><div class="donation-copy"><p class="eyebrow">UM NOVO DESTINO TAMBÉM PODE SER SOLIDÁRIO</p><h2>Não quer trocar? <span>Que tal doar?</span></h2><p>O que está parado pode fazer a diferença na vida de alguém.</p></div><div class="container-solidario"><?=icon('house')?><p>CONTAINER<strong>SOLIDÁRIO</strong><small>Juntos, por uma comunidade melhor.</small></p></div><a class="button outline" href="<?=e(url('donations'))?>">Conheça a iniciativa <?=icon('arrow')?></a></section><section class="trust-note"><?=icon('shield')?><p>Uma comunidade feita para boas trocas.<span>Acessórios e itens para pets são bem-vindos. Animais vivos não fazem parte das trocas.</span></p><a class="text-button" href="<?=e(url('rules'))?>">Regras da comunidade</a></section>
 <?php
}
function renderAuth(string $r):void{echo '<section class="form-panel"><p class="eyebrow">SEU ESPAÇO PARA NOVAS TROCAS</p>';
 if($r==='register'){echo '<h1>Comece gratuitamente.</h1><p>Crie sua conta para anunciar ou conversar. Nenhum anúncio é necessário para fazer uma proposta.</p>';beginForm('register');field('name','Seu nome','',max:100);field('email','E-mail','',type:'email',max:190);field('password','Senha (12 a 72 caracteres)','',type:'password',max:72);field('city','Cidade','',max:120);stateSelect();echo '<label class="check-label"><input type="checkbox" name="terms" required>Li e aceito as <a href="'.e(url('rules')).'" target="_blank">regras</a> e a <a href="'.e(url('privacy')).'" target="_blank">privacidade</a>.</label>';submit('Criar minha conta');echo '<p>Já tem conta? <a href="'.e(url('login')).'">Entrar</a></p>';}
 elseif($r==='login'){echo '<h1>Bem-vindo de volta.</h1>';beginForm('login');field('email','E-mail','',type:'email',max:190);field('password','Senha','',type:'password',max:72);submit('Entrar');echo '<div class="inline-actions"><a href="'.e(url('forgot')).'">Esqueci minha senha</a><a href="'.e(url('register')).'">Criar conta grátis</a></div>';}
 elseif($r==='forgot'){echo '<h1>Recuperar senha.</h1><p>Enviaremos um link para o e-mail da sua conta.</p>';beginForm('forgot');field('email','E-mail','',type:'email',max:190);submit('Solicitar recuperação');}
 else{$token=(string)($_GET['token']??$_POST['token']??'');echo '<h1>Escolha uma nova senha.</h1>';beginForm('reset');hidden('token',$token);field('password','Nova senha (12 a 72 caracteres)','',type:'password',max:72);submit('Salvar nova senha');}echo '</section>';
}
function renderAccount():void{$u=requireUser();accountNav();?><section class="page-heading"><p class="eyebrow">MINHA CONTA</p><h1>Olá, <?=e($u['name'])?>.</h1><p><?=e($u['city'])?>/<?=e($u['state'])?> · <?=e($u['email'])?></p></section><?php if(!(int)$u['email_verified']):?><div class="notice">Confirme seu e-mail para anunciar e conversar.<?php beginForm('verify_resend');submit('Reenviar confirmação');?></div><?php endif;?><div class="account-grid"><article class="panel"><h2>Meu perfil</h2><?php beginForm('profile');field('name','Nome',$u['name'],max:100);field('city','Cidade',$u['city'],max:120);stateSelect($u['state']);submit('Salvar perfil');?></article><article class="panel"><h2>Minha senha</h2><?php beginForm('password');field('password','Senha atual','',type:'password',max:72);field('new_password','Nova senha','',type:'password',max:72);submit('Alterar senha');?></article></div><div class="inline-actions"><a class="button outline" href="<?=e(url('export'))?>">Baixar meus dados</a><a class="button outline" href="<?=e(url('close-account'))?>">Encerrar minha conta</a><?php beginForm('logout','inline-form');submit('Sair');?></div><section class="panel"><h2>Minhas revisões</h2><?php foreach(['reports'=>'Denúncia','appeals'=>'Contestação'] as $table=>$label)foreach(sql("SELECT id,status,resolution,created_at FROM $table WHERE user_id=? ORDER BY id DESC LIMIT 10",[$u['id']])->fetchAll() as $feedback)echo '<p><strong>'.e($label).' #'.(int)$feedback['id'].'</strong> '.pill($feedback['status']).' '.e($feedback['resolution']).'</p';?></section><?php }
function renderPublish():void{$u=requireUser();accountNav();$id=(int)($_GET['id']??0);$l=$id?ownListing($id):[];echo '<section class="form-panel wide"><p class="eyebrow">UMA NOVA POSSIBILIDADE</p><h1>'.($id?'Editar anúncio.':'O que você quer trocar?').'</h1><p>Anúncios e alterações passam por moderação. Animais vivos não são permitidos.</p>';if(!(int)$u['email_verified']){echo '<div class="notice">Confirme seu e-mail em Minha conta antes de anunciar.</div>';}echo '<form method="post" enctype="multipart/form-data" class="modal-form">'.csrfField();hidden('action','save_listing');hidden('id',$id);field('title','Nome do item',$l['title']??'',max:100);area('description','Descrição, detalhes e o que acompanha',$l['description']??'');selectField('category','Categoria',array_map(static fn($x)=>$x[0],categories()),$l['category']??'electronics');selectField('condition_label','Estado do item',array_combine(['Novo','Como novo','Usado, bom estado','Usado, com detalhes'],['Novo','Como novo','Usado, bom estado','Usado, com detalhes']),$l['condition_label']??'Usado, bom estado');field('wanted','O que você gostaria de receber?',$l['wanted']??'',max:200);echo '<p class="help">Ex.: celular, TV ou notebook. A preferência ajuda nos matches, mas outras pessoas podem propor itens diferentes.</p>';field('city','Cidade do item',$l['city']??$u['city'],max:120);stateSelect($l['state']??$u['state']);echo '<label class="check-label"><input type="checkbox" name="open_offers" '.(($l['open_offers']??1)?'checked':'').'>Estou aberto a outras propostas.</label>';if($id){echo '<div class="photo-keep">';foreach(sql('SELECT id FROM photos WHERE listing_id=? ORDER BY position_num,id',[$id])->fetchAll() as $p)echo '<label><img src="'.e(mediaUrl((int)$p['id'])).'" alt="Foto atual"><span><input type="checkbox" name="keep_photos[]" value="'.(int)$p['id'].'" checked> Manter foto</span></label>';echo '</div>';}echo '<label>Fotos (1 a 4, até 5 MB cada)<input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple '.(!$id?'required':'').'></label><div id="upload-preview"></div><label class="check-label"><input type="checkbox" name="rules" required>Sou responsável pelo item, descrevi seu estado e meu anúncio segue as <a href="'.e(url('rules')).'" target="_blank">regras</a>.</label>';submit('Salvar e enviar para moderação');echo '</section>';}
function renderMyListings():void{$u=requireUser();accountNav();echo '<section class="page-heading"><h1>Meus anúncios.</h1><a class="button primary" href="'.e(url('publish')).'">Anunciar gratuitamente</a></section>';$items=sql('SELECT * FROM listings WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']])->fetchAll();if(!$items)echo '<div class="empty-state"><h2>Você ainda não anunciou.</h2><p>Você pode conversar com outros anunciantes mesmo assim.</p></div>';foreach($items as $l){echo '<article class="panel listing-manage"><div><h2>'.e($l['title']).'</h2>'.pill($l['status']).'<p>'.e($l['moderation_reason']).'</p></div><div class="inline-actions"><a class="button outline" href="'.e(url('listing',['id'=>$l['id']])).'">Ver anúncio</a>';if(!in_array($l['status'],['TRADED','DELETED'],true)){echo '<a class="button outline" href="'.e(url('publish',['id'=>$l['id']])).'">Editar</a>';foreach(['PAUSED'=>'Pausar','TRADED'=>'Marcar como trocado','DELETED'=>'Excluir'] as $state=>$label){beginForm('listing_state','inline-form');hidden('id',$l['id']);hidden('status',$state);submit($label);}if($l['status']==='PAUSED'){beginForm('listing_state','inline-form');hidden('id',$l['id']);hidden('status','PENDING');submit('Solicitar publicação');}if($l['status']==='REJECTED')echo '<a href="'.e(url('appeal',['id'=>$l['id']])).'">Contestar decisão</a>';}echo '</div></article>';}}
function renderListing():void{$l=listing((int)($_GET['id']??0),true);$u=currentUser();$mine=$u&&(int)$l['user_id']===(int)$u['id'];?><section class="listing-detail"><div class="gallery"><?php foreach(sql('SELECT id FROM photos WHERE listing_id=? ORDER BY position_num,id',[$l['id']])->fetchAll() as $p):?><a href="<?=e(mediaUrl((int)$p['id']))?>" target="_blank" rel="noopener"><img src="<?=e(mediaUrl((int)$p['id']))?>" alt="Foto de <?=e($l['title'])?>"></a><?php endforeach;?></div><div class="detail-copy"><p class="eyebrow"><?=e(categories()[$l['category']][0])?> · <?=e($l['city'])?>/<?=e($l['state'])?></p><h1><?=e($l['title'])?></h1><?=pill($l['status'])?><p><?=e($l['condition_label'])?></p><p class="preserve-text"><?=e($l['description'])?></p><div class="wanted"><?=icon('swap')?> Interesse em: <strong><?=e($l['wanted'])?></strong></div><p><?=$l['open_offers']?'Outras propostas também são bem-vindas.':'Este anunciante indicou preferência pelo item acima. Você ainda pode conversar e propor.'?></p><p>Anunciado por <?=e($l['owner_name'])?>.</p><?php if($mine):?><a class="button outline" href="<?=e(url('publish',['id'=>$l['id']]))?>">Editar meu anúncio</a><?php elseif($l['status']==='ACTIVE'&&$l['owner_status']==='ACTIVE'):?><a class="button primary" href="<?=e(url('propose',['id'=>$l['id']]))?>">Quero propor uma troca <?=icon('arrow')?></a><p class="help">Você não precisa publicar um anúncio para fazer uma proposta.</p><a class="text-button" href="<?=e(url('report',['listing_id'=>$l['id']]))?>">Denunciar anúncio</a><?php endif;?><?php if($l['status']!=='ACTIVE'&&($mine||($u&&$u['role']==='ADMIN'))):?><div class="notice"><?=e($l['moderation_reason'])?></div><?php endif;?></div></section><aside class="notice">Confira os itens e combine a troca em um local público. Não envie dinheiro para garantir uma troca.</aside><?php }
function renderPropose():void{$u=requireUser();$l=listing((int)($_GET['id']??0));if((int)$l['user_id']===(int)$u['id'])throw new RuntimeException('Este anúncio é seu.');echo '<section class="form-panel"><h1>Vamos começar uma conversa.</h1><p>Proposta para '.e($l['title']).'. Você pode oferecer um item mesmo sem ter anúncio.</p>';beginForm('propose');hidden('listing_id',$l['id']);field('offer_title','O que você oferece?','',max:120);$options=['0'=>'Não tenho anúncio — vou descrever o item'];foreach(sql("SELECT id,title FROM listings WHERE user_id=? AND status='ACTIVE' ORDER BY id DESC",[$u['id']])->fetchAll() as $x)$options[$x['id']]=$x['title'];selectField('offered_listing_id','Vincular um anúncio meu (opcional)',$options);area('body','Conte sobre seu item e proponha a troca','',2000);submit('Enviar proposta');echo '<p class="help">Mensagens podem passar por moderação antes de aparecer para a outra pessoa.</p></section>';}
function renderInbox():void{$u=requireUser();accountNav();echo '<section class="page-heading"><h1>Suas conversas.</h1></section>';$rows=sql('SELECT p.*,l.title,u.name AS sender_name,v.name AS recipient_name FROM proposals p JOIN listings l ON l.id=p.listing_id JOIN users u ON u.id=p.sender_id JOIN users v ON v.id=p.recipient_id WHERE p.sender_id=? OR (p.recipient_id=? AND p.status<>\'PENDING\') ORDER BY p.updated_at DESC LIMIT 100',[$u['id'],$u['id']])->fetchAll();if(!$rows)echo '<div class="empty-state"><h2>Uma boa troca começa com uma conversa.</h2><a class="button outline" href="'.e(url()).'">Explorar anúncios</a></div>';foreach($rows as $p){$unread=count(unreadMessages((int)$u['id'],(int)$p['id']));echo '<a class="panel inbox-row" data-inbox-thread="'.(int)$p['id'].'" href="'.e(url('thread',['id'=>$p['id']])).'"><div><h2>'.e($p['title']).'</h2><p>'.e((int)$u['id']===(int)$p['sender_id']?$p['recipient_name']:$p['sender_name']).' · Oferece: '.e($p['offer_title']).'</p></div>'.pill($p['status']).'<span class="status-pill" data-thread-unread '.($unread?'':'hidden').'>'.$unread.' novas</span>'.'</a>';}}
function threadMessages(array $p,array $u):array{return array_reverse(sql("SELECT m.*,u.name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.proposal_id=? AND (m.status='ACTIVE' OR m.sender_id=?) ORDER BY m.id DESC LIMIT 200",[$p['id'],$u['id']])->fetchAll());}
function renderThread():void{$u=requireUser();$p=thread((int)($_GET['id']??0));accountNav();$messages=threadMessages($p,$u);markThreadRead($p,$u,$messages);echo '<section class="page-heading"><p class="eyebrow">PROPOSTA DE TROCA</p><h1>'.e($p['listing_title']).'</h1><p>Oferta: '.e($p['offer_title']).' · '.e($p['sender_name']).' ↔ '.e($p['recipient_name']).'</p>'.pill($p['status']).'</section><section class="thread-panel"><div class="message-list" data-thread="'.(int)$p['id'].'">';foreach($messages as $m){echo '<article class="message '.((int)$m['sender_id']===(int)$u['id']?'mine':'').'"><strong>'.e($m['name']).'</strong><p>'.nl2br(e($m['body'])).'</p><small>'.e($m['created_at']).' UTC</small>';if($m['status']!=='ACTIVE')echo '<span class="status-pill">'.e($m['status']==='REJECTED'?'Recusada: '.$m['moderation_reason']:'Aguardando moderação').'</span>';else echo '<a class="message-report" href="'.e(url('report',['proposal_id'=>$p['id'],'message_id'=>$m['id']])).'">Denunciar</a>';echo '</article>';}echo '</div><p class="help">As mensagens são verificadas para proteger as pessoas. A equipe pode revisar conteúdo sinalizado.</p>';if(!in_array($p['status'],['REJECTED','CLOSED'],true)&&$p['sender_status']==='ACTIVE'&&$p['recipient_status']==='ACTIVE'){beginForm('message');hidden('proposal_id',$p['id']);area('body','Sua mensagem','',2000);submit('Enviar mensagem');}echo '</section><div class="inline-actions">';if($p['status']==='OPEN'&&(int)$p['recipient_id']===(int)$u['id'])foreach(['ACCEPTED'=>'Aceitar proposta','REJECTED'=>'Recusar proposta'] as $state=>$label){beginForm('proposal_state','inline-form');hidden('id',$p['id']);hidden('status',$state);submit($label);}if($p['status']==='ACCEPTED'){echo '<p>Confirmação: '.((int)$p['sender_confirmed']?'remetente confirmou':'remetente pendente').' · '.((int)$p['recipient_confirmed']?'destinatário confirmou':'destinatário pendente').'</p>';beginForm('proposal_state','inline-form');hidden('id',$p['id']);hidden('status','CONFIRMED');submit('Já recebi meu item — confirmar troca');}if(!in_array($p['status'],['COMPLETED','CLOSED','REJECTED'],true)){beginForm('proposal_state','inline-form');hidden('id',$p['id']);hidden('status','CLOSED');submit('Encerrar conversa');}echo '</div>';}
function renderMatches():void{$u=requireUser();sql('UPDATE match_notifications SET seen_a=1 WHERE user_a=?',[$u['id']]);sql('UPDATE match_notifications SET seen_b=1 WHERE user_b=?',[$u['id']]);accountNav();echo '<section class="page-heading"><p class="eyebrow">TENHO + PROCURO = POSSIBILIDADES</p><h1>Interesses que combinam.</h1><p>Uma sugestão nunca limita suas propostas. Você pode conversar com qualquer anunciante.</p></section>';$mine=sql("SELECT * FROM listings WHERE user_id=? AND status='ACTIVE' ORDER BY id DESC LIMIT 30",[$u['id']])->fetchAll();if(!$mine){echo '<div class="empty-state"><h2>Conte o que você tem e o que procura.</h2><p>Os matches aparecem a partir dos seus anúncios publicados. Para negociar sem anunciar, explore os itens e faça uma proposta.</p><a class="button primary" href="'.e(url('publish')).'">Anunciar um item</a><a class="button outline" href="'.e(url()).'">Explorar anúncios</a></div>';return;}$found=false;foreach($mine as $a){$candidates=sql("SELECT l.* FROM match_notifications n JOIN listings l ON l.id=CASE WHEN n.listing_a=? THEN n.listing_b ELSE n.listing_a END JOIN users v ON v.id=l.user_id WHERE (n.listing_a=? OR n.listing_b=?) AND l.status='ACTIVE' AND v.status='ACTIVE'",[$a['id'],$a['id'],$a['id']])->fetchAll();$matches=[];foreach($candidates as $b){$score=matchScore($a,$b);if($score)$matches[]=[$score,$b];}usort($matches,static fn($x,$y)=>$y[0]<=>$x[0]);if(!$matches)continue;$found=true;echo '<section class="match-group"><h2>Para seu '.e($a['title']).'</h2><p>Você procura '.e($a['wanted']).'. Estes anúncios têm interesses recíprocos.</p><div class="listing-grid">';foreach(array_slice($matches,0,8) as [$score,$b])card($b);echo '</div></section>';}if(!$found)echo '<div class="empty-state"><h2>Ainda não encontramos interesses recíprocos.</h2><p>Novos anúncios podem trazer novas possibilidades. Enquanto isso, explore e faça outras propostas.</p><a class="button outline" href="'.e(url()).'">Explorar anúncios</a></div>';echo '<p class="help">Sugestões calculadas entre os anúncios disponíveis. Prioridade para interesses compatíveis na mesma cidade e estado. A IA amplia a interpretação quando configurada; há comparação por termos como alternativa.</p>';}
